insert into public.food (slug, name, arabic, kind, description, ingredients, price_min_egp, price_max_egp, vegetarian, background) values ('koshari', 'Koshari', 'كشري', 'street', 'Egypt''s national comfort food: layers of rice, lentils and pasta topped with spiced tomato sauce, chickpeas and crispy onions.', array['Rice','Brown lentils','Macaroni','Chickpeas','Tomato sauce','Fried onions','Garlic vinegar (dakka)']::text[], 40, 120, 'yes', 'A 19th-century mix of Indian, Italian and Middle Eastern ingredients that became Cairo''s favourite cheap, filling meal.') on conflict (slug) do nothing;
insert into public.food (slug, name, arabic, kind, description, ingredients, price_min_egp, price_max_egp, vegetarian, background) values ('ful-medames', 'Ful medames', 'فول مدمس', 'street', 'Slow-cooked fava beans mashed with olive oil, cumin and lemon, eaten with baladi bread for breakfast.', array['Fava beans','Olive oil','Cumin','Lemon','Garlic','Baladi bread']::text[], 15, 60, 'yes', 'Fava beans have been eaten in Egypt since antiquity; street carts still cook them overnight in large pots called idra.') on conflict (slug) do nothing;
insert into public.food (slug, name, arabic, kind, description, ingredients, price_min_egp, price_max_egp, vegetarian, background) values ('taameya', 'Taameya', 'طعمية', 'street', 'Egyptian falafel, made with fava beans instead of chickpeas, so it is green and fluffy inside.', array['Fava beans','Parsley','Dill','Coriander','Onion','Sesame']::text[], 10, 40, 'yes', 'Coptic Christians traditionally ate taameya during fasting periods when animal products are avoided.') on conflict (slug) do nothing;
insert into public.food (slug, name, arabic, kind, description, ingredients, price_min_egp, price_max_egp, vegetarian, background) values ('molokhia', 'Molokhia', 'ملوخية', 'main', 'A silky green soup of finely chopped jute leaves with a garlic and coriander finish, served with rice or bread.', array['Jute mallow leaves','Stock','Garlic','Ground coriander','Ghee']::text[], 60, 200, 'often', 'The final ''tasha'' — sizzling garlic poured in — is so important that families say the cook should gasp as it hits the pot.') on conflict (slug) do nothing;
insert into public.food (slug, name, arabic, kind, description, ingredients, price_min_egp, price_max_egp, vegetarian, background) values ('mahshi', 'Mahshi', 'محشي', 'main', 'Vegetables and vine leaves stuffed with herbed rice and simmered in tomato broth.', array['Vine leaves','Courgette','Peppers','Aubergine','Rice','Dill','Tomato']::text[], 80, 250, 'often', 'A family dish; aunts and grandmothers often roll mahshi together before holidays.') on conflict (slug) do nothing;
insert into public.food (slug, name, arabic, kind, description, ingredients, price_min_egp, price_max_egp, vegetarian, background) values ('feteer', 'Feteer meshaltet', 'فطير مشلتت', 'main', 'A buttery, flaky layered pastry eaten sweet with honey and cream, or savoury with cheese and meat.', array['Flour','Ghee','Honey or molasses','Cheese']::text[], 80, 300, 'often', 'A countryside speciality, traditionally offered to guests and brought back from village visits.') on conflict (slug) do nothing;
insert into public.food (slug, name, arabic, kind, description, ingredients, price_min_egp, price_max_egp, vegetarian, background) values ('hawawshi', 'Hawawshi', 'حواوشي', 'street', 'Baladi bread stuffed with spiced minced meat, onions and peppers, then baked until crisp.', array['Minced beef','Onion','Chilli','Baladi bread']::text[], 50, 150, 'no', 'Popularly said to be named after the Cairo butcher who first sold it; today it is a favourite late-night street snack.') on conflict (slug) do nothing;
insert into public.food (slug, name, arabic, kind, description, ingredients, price_min_egp, price_max_egp, vegetarian, background) values ('basbousa', 'Basbousa & desserts', 'بسبوسة', 'dessert', 'Syrup-soaked semolina cake. Also try om ali (bread pudding), konafa and roz bel laban (rice pudding).', array['Semolina','Yogurt','Sugar syrup','Coconut','Almonds']::text[], 30, 120, 'yes', 'Ramadan evenings bring out trays of konafa and qatayef across the country.') on conflict (slug) do nothing;
insert into public.food (slug, name, arabic, kind, description, ingredients, price_min_egp, price_max_egp, vegetarian, background) values ('karkade', 'Karkade & drinks', 'كركديه', 'drink', 'Deep red hibiscus tea, served hot in winter and iced in summer. Also try sugarcane juice (asab) and mint tea.', array['Dried hibiscus','Sugar','Water']::text[], 15, 60, 'yes', 'Aswan is famous for its hibiscus; it is also the traditional welcome drink at Nubian weddings.') on conflict (slug) do nothing;
insert into public.historical_stories (id, name, dates, summary, child_version, place_slugs, sort) values ('predynastic', 'Before the pharaohs', 'c. 6000–3100 BCE', 'Farming villages grew along the Nile. Kingdoms in the north and south formed and were finally united.', 'People learned to grow food beside the river. Little villages became two big kingdoms that later joined together.', array['fayoum']::text[], 0) on conflict (id) do nothing;
insert into public.historical_stories (id, name, dates, summary, child_version, place_slugs, sort) values ('old-kingdom', 'Old Kingdom', 'c. 2686–2181 BCE', 'The age of the pyramids, from Djoser''s Step Pyramid at Saqqara to the Great Pyramid at Giza.', 'Kings built giant pyramids as tombs. Thousands of skilled workers moved huge stone blocks to build them.', array['saqqara','giza']::text[], 1) on conflict (id) do nothing;
insert into public.historical_stories (id, name, dates, summary, child_version, place_slugs, sort) values ('middle-new-kingdom', 'Middle & New Kingdoms', 'c. 2055–1069 BCE', 'Thebes (Luxor) became the religious capital. Hatshepsut, Tutankhamun and Ramesses II ruled in this period.', 'Pharaohs were buried in secret tombs in a valley, and built enormous temples with giant statues.', array['luxor','abu-simbel','aswan']::text[], 2) on conflict (id) do nothing;
insert into public.historical_stories (id, name, dates, summary, child_version, place_slugs, sort) values ('greco-roman', 'Greek & Roman Egypt', '332 BCE–641 CE', 'Alexander the Great founded Alexandria. The Ptolemies, including Cleopatra VII, ruled, followed by Rome.', 'A Greek king built a new city by the sea with a famous library and a lighthouse that was a wonder of the world.', array['alexandria','siwa','aswan']::text[], 3) on conflict (id) do nothing;
insert into public.historical_stories (id, name, dates, summary, child_version, place_slugs, sort) values ('coptic', 'Coptic Christian Egypt', '1st–7th century CE', 'Christianity spread early in Egypt. The monastic tradition began in its deserts.', 'Some people went to live quietly in the desert to pray. They started the very first monasteries.', array['islamic-coptic-cairo','dahab']::text[], 4) on conflict (id) do nothing;
insert into public.historical_stories (id, name, dates, summary, child_version, place_slugs, sort) values ('islamic', 'Islamic Cairo', '641–1517 CE', 'Fustat and then Cairo grew under the Fatimids, Ayyubids and Mamluks, who built Al-Azhar and the Citadel.', 'Cairo filled with beautiful mosques, markets and gates. Some of its streets are almost 1,000 years old.', array['islamic-coptic-cairo','cairo']::text[], 5) on conflict (id) do nothing;
insert into public.historical_stories (id, name, dates, summary, child_version, place_slugs, sort) values ('modern', 'Modern Egypt', '1805–today', 'From Muhammad Ali''s reforms and the Suez Canal to today''s Grand Egyptian Museum and new cities.', 'Egypt built railways, a canal joining two seas, and a brand-new museum for Tutankhamun''s treasures.', array['cairo','giza','alexandria']::text[], 6) on conflict (id) do nothing;
insert into public.walking_routes (slug, title, duration, distance_km, intro, tips, status) values ('islamic-cairo-3-hours', 'Islamic Cairo in three hours', 'About 3 hours', 1.8, 'Walk south along Al-Muizz Street, the main street of Fatimid Cairo, from the northern gates to Bab Zuweila.', array['Start in the morning before the heat and the market crowds.','Carry a scarf for mosque visits and small notes for entrance fees and tips.','Friday midday prayers close some mosques to visitors.']::text[], 'awaiting') on conflict (slug) do nothing;
insert into public.route_stops (route_slug, position, name, lat, lng, minutes, story) values ('islamic-cairo-3-hours', 0, 'Bab al-Futuh', 30.0549, 31.2636, 15, 'One of the stone gates built in the 11th century to protect Fatimid Cairo.') on conflict (route_slug, position) do nothing;
insert into public.route_stops (route_slug, position, name, lat, lng, minutes, story) values ('islamic-cairo-3-hours', 1, 'Mosque of al-Hakim', 30.0545, 31.2634, 20, 'A huge Fatimid mosque with an open courtyard and distinctive minarets.') on conflict (route_slug, position) do nothing;
insert into public.route_stops (route_slug, position, name, lat, lng, minutes, story) values ('islamic-cairo-3-hours', 2, 'Bayt al-Suhaymi', 30.0522, 31.2621, 30, 'An Ottoman-era merchant''s house with wooden mashrabiya screens and a garden courtyard.') on conflict (route_slug, position) do nothing;
insert into public.route_stops (route_slug, position, name, lat, lng, minutes, story) values ('islamic-cairo-3-hours', 3, 'Qalawun Complex', 30.0497, 31.2611, 25, 'A 13th-century Mamluk hospital, school and mausoleum.') on conflict (route_slug, position) do nothing;
insert into public.route_stops (route_slug, position, name, lat, lng, minutes, story) values ('islamic-cairo-3-hours', 4, 'Khan el-Khalili', 30.0477, 31.2623, 40, 'Cairo''s historic bazaar. Stop for mint tea at a traditional café.') on conflict (route_slug, position) do nothing;
insert into public.route_stops (route_slug, position, name, lat, lng, minutes, story) values ('islamic-cairo-3-hours', 5, 'Al-Azhar Mosque', 30.0457, 31.2627, 25, 'Founded in 970 CE, the heart of one of the world''s oldest universities.') on conflict (route_slug, position) do nothing;
insert into public.route_stops (route_slug, position, name, lat, lng, minutes, story) values ('islamic-cairo-3-hours', 6, 'Al-Ghuri Complex', 30.0453, 31.2588, 15, 'Late Mamluk mosque and mausoleum; Sufi Tanoura performances are held nearby on some evenings.') on conflict (route_slug, position) do nothing;
insert into public.route_stops (route_slug, position, name, lat, lng, minutes, story) values ('islamic-cairo-3-hours', 7, 'Bab Zuweila', 30.0428, 31.2577, 20, 'The southern gate. Climb the minarets for one of the best views over old Cairo.') on conflict (route_slug, position) do nothing;
insert into public.walking_routes (slug, title, duration, distance_km, intro, tips, status) values ('coptic-cairo-90-minutes', 'Coptic Cairo in 90 minutes', 'About 1.5 hours', 1.2, 'A compact walk inside the walls of the old Roman fortress of Babylon, starting at Mar Girgis metro station.', array['Take Metro Line 1 to Mar Girgis.','Dress modestly; some churches hold services.','Photography rules differ inside churches — check signs.']::text[], 'awaiting') on conflict (slug) do nothing;
insert into public.route_stops (route_slug, position, name, lat, lng, minutes, story) values ('coptic-cairo-90-minutes', 0, 'Mar Girgis metro', 30.006, 31.2297, 5, 'Exit straight into the Roman towers of the Babylon fortress.') on conflict (route_slug, position) do nothing;
insert into public.route_stops (route_slug, position, name, lat, lng, minutes, story) values ('coptic-cairo-90-minutes', 1, 'Hanging Church', 30.0053, 31.2301, 20, 'Named because it was built over a gatehouse of the fortress.') on conflict (route_slug, position) do nothing;
insert into public.route_stops (route_slug, position, name, lat, lng, minutes, story) values ('coptic-cairo-90-minutes', 2, 'Coptic Museum', 30.006, 31.2302, 30, 'The world''s largest collection of Coptic Christian art.') on conflict (route_slug, position) do nothing;
insert into public.route_stops (route_slug, position, name, lat, lng, minutes, story) values ('coptic-cairo-90-minutes', 3, 'Church of St Sergius and Bacchus', 30.0058, 31.2308, 15, 'Tradition says the Holy Family sheltered here.') on conflict (route_slug, position) do nothing;
insert into public.route_stops (route_slug, position, name, lat, lng, minutes, story) values ('coptic-cairo-90-minutes', 4, 'Ben Ezra Synagogue', 30.0049, 31.2313, 10, 'Where the Cairo Geniza, a huge medieval document archive, was found.') on conflict (route_slug, position) do nothing;
insert into public.route_stops (route_slug, position, name, lat, lng, minutes, story) values ('coptic-cairo-90-minutes', 5, 'Mosque of Amr ibn al-As', 30.0103, 31.2335, 15, 'Site of the first mosque built in Egypt, in 642 CE.') on conflict (route_slug, position) do nothing;
