insert into public.bucket_list_activities (id, title, destination_slug, published, featured, data, last_reviewed, created_at) values ('luxor-balloon-sunrise', 'Watch the sun rise over Luxor from a balloon', 'luxor', true, true, '{"published":true,"featured":true,"createdAt":"2026-11-13","lastReviewed":"2026-11-13","id":"luxor-balloon-sunrise","title":"Watch the sun rise over Luxor from a balloon","description":"Drift above the temples, fields and the Nile as the light comes up over the West Bank.","destination":"luxor","categories":["adventure","photography"],"effort":"easy","duration":"Early start; about 3–4 hours with transfers","bestMonths":[10,11,12,1,2,3,4],"season":{"note":"Flights run most of the year but are cancelled in strong wind.","verified":false},"tips":["Book a licensed operator and ask about their safety record.","Bring a warm layer — dawn is chilly in winter."],"photo":"luxorBalloons"}'::jsonb, '2026-11-13', '2026-11-13') on conflict (id) do nothing;
insert into public.bucket_list_activities (id, title, destination_slug, published, featured, data, last_reviewed, created_at) values ('felucca-aswan', 'Sail the Nile on a felucca at sunset', 'aswan', true, true, '{"published":true,"featured":true,"createdAt":"2026-11-13","lastReviewed":"2026-11-13","id":"felucca-aswan","title":"Sail the Nile on a felucca at sunset","description":"No engine, just wind: glide past Elephantine Island and the granite boulders of Aswan.","destination":"aswan","categories":["relaxation","culture","photography"],"effort":"easy","duration":"1–2 hours","bestMonths":[10,11,12,1,2,3,4],"tips":["Agree the price and duration before you set off."],"photo":"heroAswan"}'::jsonb, '2026-11-13', '2026-11-13') on conflict (id) do nothing;
insert into public.bucket_list_activities (id, title, destination_slug, published, featured, data, last_reviewed, created_at) values ('red-sea-reef', 'Dive or snorkel a Red Sea reef', 'dahab', true, true, '{"published":true,"featured":true,"createdAt":"2026-11-13","lastReviewed":"2026-11-13","id":"red-sea-reef","title":"Dive or snorkel a Red Sea reef","description":"Coral gardens and bright fish a few fins from the shore — no experience needed to snorkel.","destination":"dahab","categories":["adventure","nature"],"effort":"moderate","duration":"Half day to a full day","bestMonths":[4,5,6,9,10,11],"tips":["Dive with a certified centre.","Use reef-safe sunscreen and never touch the coral."],"photo":"sharm"}'::jsonb, '2026-11-13', '2026-11-13') on conflict (id) do nothing;
insert into public.bucket_list_activities (id, title, destination_slug, published, featured, data, last_reviewed, created_at) values ('white-desert-night', 'Sleep under the stars in the White Desert', 'white-desert', true, true, '{"published":true,"featured":true,"createdAt":"2026-11-13","lastReviewed":"2026-11-13","id":"white-desert-night","title":"Sleep under the stars in the White Desert","description":"Camp among chalk formations that glow at sunset and turn silver under the moon.","destination":"white-desert","categories":["adventure","nature","photography"],"effort":"moderate","duration":"1–2 nights, usually from Bahariya Oasis","bestMonths":[10,11,12,1,2,3],"season":{"note":"Desert nights are cold in winter; summer days are very hot.","verified":false},"tips":["Go with a licensed desert operator.","Pack warm clothes for the night."],"photo":"heroWhiteDesert"}'::jsonb, '2026-11-13', '2026-11-13') on conflict (id) do nothing;
insert into public.bucket_list_activities (id, title, destination_slug, published, featured, data, last_reviewed, created_at) values ('muizz-street-walk', 'Walk al-Muizz Street in Historic Cairo', 'islamic-coptic-cairo', true, false, '{"published":true,"featured":false,"createdAt":"2026-11-13","lastReviewed":"2026-11-13","id":"muizz-street-walk","title":"Walk al-Muizz Street in Historic Cairo","description":"A thousand years of mosques, madrasas and markets along one of Cairo''s oldest streets.","destination":"islamic-coptic-cairo","categories":["history","culture","photography"],"effort":"easy","duration":"About 3 hours","bestMonths":[10,11,12,1,2,3,4],"tips":["Dress modestly to enter mosques.","Follow our 3-hour walking route."],"photo":"islamicCairo","link":{"href":"/travel-smart#walks","label":"Walking route"}}'::jsonb, '2026-11-13', '2026-11-13') on conflict (id) do nothing;
