insert into public.media_items (id, title, kind, destinations, status, featured, data, last_reviewed, created_at) values ('great-pyramid-how', 'How the Great Pyramid was built — what we know, and what we don''t', 'original', array['giza','saqqara','cairo']::text[], 'draft', true, '{"id":"great-pyramid-how","title":"How the Great Pyramid was built — what we know, and what we don''t","summary":"From the first step pyramid to Merer''s 4,500-year-old logbook, the workers'' town and the ramp debate: the evidence behind Khufu''s pyramid, with the open questions kept open.","kind":"original","destinations":["giza","saqqara","cairo"],"period":"Old Kingdom, c. 2630–2560 BCE","durationSec":290,"explainerId":"great-pyramid-how","credit":"Discover Egypt (original animation)","license":"© Discover Egypt","chapters":[{"start":0,"title":"The Horizon of Khufu"},{"start":23.562,"title":"From steps to a true pyramid"},{"start":49.754,"title":"A mountain of stone"},{"start":79.215,"title":"Merer''s logbook"},{"start":110.6,"title":"The river road"},{"start":146.731,"title":"Who built it"},{"start":186.515,"title":"Getting the stones up"},{"start":229.185,"title":"Pointing north"},{"start":262.492,"title":"When you visit"}],"transcript":[{"start":1.6,"text":"On the Giza plateau stands the Great Pyramid, built for King Khufu of the Fourth Dynasty and completed around 2560 BCE."},{"start":10.577,"text":"A logbook from Khufu''s own reign records its original name: Akhet-Khufu, the Horizon of Khufu."},{"start":17.246,"text":"This film separates what the evidence shows from what is still debated."},{"start":25.162,"text":"Pyramids did not appear from nowhere."},{"start":28.562,"text":"Around 2630 BCE, King Djoser''s Step Pyramid at Saqqara stacked stone platforms about 62 metres high."},{"start":35.615,"text":"King Sneferu, the first king of the Fourth Dynasty, built the Red Pyramid at Dahshur — the first with smooth, straight sides."},{"start":44.977,"text":"Khufu''s builders inherited those experiments, and went bigger."},{"start":51.354,"text":"When finished, it stood about 146 metres tall on a base roughly 230 metres a side."},{"start":58.408,"text":"Erosion and the loss of its top stones have left about 138 metres today."},{"start":64.692,"text":"A common estimate puts it at around 2.3 million blocks."},{"start":69.438,"text":"Ancient writers counted it among the wonders of the world. It is the only one of the Seven Wonders still standing."},{"start":80.815,"text":"In 2013, a French-led team under Pierre Tallet found papyri at Wadi al-Jarf, an ancient harbour on the Red Sea coast."},{"start":89.792,"text":"They are the oldest inscribed papyri yet found."},{"start":93.769,"text":"The best preserved is the logbook of an inspector named Merer, who led a crew of about 200 men."},{"start":101.977,"text":"His entries date to around the 27th year of Khufu''s reign — near the end of the build."},{"start":112.2,"text":"Merer''s crew hauled fine white limestone at the Tura quarries, across the river from Giza."},{"start":118.869,"text":"They took it by boat along the Nile and its canals to a harbour basin called She-Khufu, the Pool of Khufu."},{"start":127.846,"text":"A loaded trip took about two days. The empty return took one."},{"start":133.362,"text":"The voyage depended on high water, when the flood made the river and the canals navigable."},{"start":140.415,"text":"Pierre Tallet believes these blocks were for the pyramid''s smooth outer casing."},{"start":148.331,"text":"The Greek historian Herodotus, writing some two thousand years later, told of 100,000 men labouring for twenty years."},{"start":156.154,"text":"Archaeology tells a more grounded story."},{"start":159.554,"text":"South of the Sphinx, excavations led by Mark Lehner uncovered Heit el-Ghurab, a town with bakeries and stores that housed and fed the workforce."},{"start":169.685,"text":"On the hillside nearby, Zahi Hawass excavated a cemetery where builders and overseers were buried in their own tombs."},{"start":177.892,"text":"The excavators describe an organised, rotating Egyptian workforce — not slaves in the modern sense of the word."},{"start":188.115,"text":"How the blocks were raised is still the biggest open question."},{"start":193.246,"text":"Most Egyptologists think ramps were used, but not which kind: a straight ramp, one wrapping around the sides, or ramps inside the pyramid."},{"start":202.992,"text":"In 2018, a mission at the Hatnub alabaster quarry found a steep ramp flanked by stairs cut with post holes, dating at least to Khufu''s reign."},{"start":213.892,"text":"Ropes around wooden posts may have helped teams haul sledges up slopes of 20 percent or more."},{"start":221.331,"text":"Other experts caution that a quarry ramp does not prove how the pyramid itself was built."},{"start":230.785,"text":"The pyramid''s sides face north, south, east and west with an error of less than four minutes of arc — about one-fifteenth of a degree."},{"start":241.3,"text":"Khafre''s pyramid and Sneferu''s Red Pyramid share the same slight counterclockwise twist."},{"start":246.815,"text":"Engineer Glen Dash showed that tracking a shadow on the autumn equinox could produce exactly this kind of error."},{"start":255.023,"text":"The builders left no record of their method, so it remains one possibility among several."},{"start":264.092,"text":"Most of the white casing is gone, stripped away and reused over the centuries."},{"start":270.377,"text":"Merer''s papyri have been displayed at the Egyptian Museum in Cairo."},{"start":275.508,"text":"At Giza, the Workers'' Town and Cemetery south of the Sphinx tell the builders'' side of the story."},{"start":283.331,"text":"Every claim in this film is listed with its source below the video."}],"sources":[{"name":"Diary of Merer — Wikipedia","url":"https://en.wikipedia.org/wiki/Diary_of_Merer"},{"name":"National Geographic — The Red Sea Scrolls (2024)","url":"https://www.nationalgeographic.com/premium/article/red-sea-scrolls-pyramids-egypt"},{"name":"World History Encyclopedia — Great Pyramid of Giza","url":"https://www.worldhistory.org/Great_Pyramid_of_Giza/"},{"name":"History.com — Ancient ramp find deepens mystery (2018)","url":"https://www.history.com/news/ancient-egypt-pyramid-ramp-discovery"},{"name":"Scientific American / Live Science — Hatnub ramp (2018)","url":"https://www.scientificamerican.com/article/a-ramp-contraption-may-have-been-used-to-build-egypts-great-pyramid/"},{"name":"Ministry of Tourism and Antiquities — Workers'' Town and Cemetery","url":"https://egymonuments.gov.eg/en/monuments/workers-town-and-cemetery/"},{"name":"Smithsonian — The fall equinox and the pyramids'' alignment","url":"https://www.smithsonianmag.com/smart-news/fall-equinox-secret-pyramids-near-perfect-alignment-180968223/"},{"name":"Live Science — Great Pyramid''s near-perfect alignment","url":"https://www.livescience.com/61799-great-pyramid-near-perfect-alignment.html"}],"status":"draft","featured":true,"provenance":"original-ai-assisted","lastReviewed":null,"createdAt":"2026-11-13"}'::jsonb, null, '2026-11-13') on conflict (id) do nothing;
insert into public.media_items (id, title, kind, destinations, status, featured, data, last_reviewed, created_at) values ('moving-abu-simbel', 'Moving Abu Simbel', 'original', array['abu-simbel','aswan','nubia']::text[], 'draft', true, '{"id":"moving-abu-simbel","title":"Moving Abu Simbel","summary":"How an international campaign cut two rock temples of Ramesses II into more than a thousand blocks and rebuilt them 65 metres higher, before Lake Nasser rose.","kind":"original","destinations":["abu-simbel","aswan","nubia"],"period":"13th century BCE · rescued 1964–1968","durationSec":173,"explainerId":"moving-abu-simbel","credit":"Discover Egypt (original animation)","license":"© Discover Egypt","chapters":[{"start":0,"title":"Temples in a cliff"},{"start":18.046,"title":"Two temples"},{"start":43.146,"title":"Rising water"},{"start":57.346,"title":"Now or never"},{"start":72.315,"title":"Cut into blocks"},{"start":94.723,"title":"65 metres up"},{"start":112.385,"title":"Reopened"},{"start":131.715,"title":"The sun returns"},{"start":154.508,"title":"Philae, too"}],"transcript":[{"start":1.6,"text":"In the 13th century BCE, Ramesses II had two temples carved into a sandstone cliff above the Nile at Abu Simbel, in Nubia."},{"start":11.346,"text":"The Great Temple took about twenty years and was completed around 1265 BCE."},{"start":19.646,"text":"The Great Temple was dedicated to Amun, Re-Horakhty and Ptah — and to Ramesses himself as a god."},{"start":27.469,"text":"Four seated colossi of the king guard its entrance."},{"start":31.831,"text":"The Small Temple honours the goddess Hathor and Queen Nefertari, with six standing statues: four of Ramesses and two of Nefertari, all the same size."},{"start":44.746,"text":"In the 1960s, the Aswan High Dam began to create Lake Nasser."},{"start":50.262,"text":"Its waters would cover many of Nubia''s ancient temples — Abu Simbel among them."},{"start":58.946,"text":"In 1960, UNESCO launched an international appeal to save the monuments of Nubia."},{"start":64.846,"text":"Its magazine, the UNESCO Courier, published a special report titled Abu Simbel: Now or Never."},{"start":73.915,"text":"Work began in 1964, behind a temporary cofferdam that held back the rising water."},{"start":80.2,"text":"Teams sawed both temples, and the rock around them, into more than a thousand blocks."},{"start":86.869,"text":"Sources give between 1,035 and 1,042 blocks, averaging about 20 tonnes and weighing up to 30."},{"start":96.323,"text":"Each block was numbered, lifted, and reassembled about 65 metres higher and around 200 metres back from the river."},{"start":104.531,"text":"The temples kept their original orientation, rebuilt inside a concrete dome hidden beneath an artificial hill."},{"start":113.985,"text":"The relocated temples were officially inaugurated on 22 September 1968."},{"start":118.731,"text":"The rescue cost around 40 million dollars, shared by many nations."},{"start":123.862,"text":"In 1979, the Nubian Monuments from Abu Simbel to Philae became a UNESCO World Heritage Site."},{"start":133.315,"text":"Twice a year, on 22 February and 22 October, the rising sun reaches deep into the Great Temple''s sanctuary."},{"start":141.523,"text":"Since the move, the alignment falls one day later than it did before."},{"start":147.423,"text":"Some say the dates mark Ramesses'' birthday and coronation, but that is not confirmed."},{"start":156.108,"text":"Abu Simbel was not alone. Between 1977 and 1980, the temples of Philae were dismantled into about 40,000 blocks and rebuilt on nearby Agilkia Island."},{"start":166.623,"text":"Every claim in this film is listed with its source below the video."}],"sources":[{"name":"UNESCO World Heritage Centre — Nubian Monuments from Abu Simbel to Philae","url":"https://whc.unesco.org/en/list/88/"},{"name":"Historical Marker Database — The Salvage of Abu Simbel Temples","url":"https://www.hmdb.org/m.asp?m=289511"},{"name":"International Campaign to Save the Monuments of Nubia — Wikipedia","url":"https://en.wikipedia.org/wiki/International_Campaign_to_Save_the_Monuments_of_Nubia"},{"name":"Abu Simbel — Wikipedia","url":"https://en.wikipedia.org/wiki/Abu_Simbel"},{"name":"Voyaged — How ancient temples were dismantled and rebuilt","url":"https://www.voyagedmagazine.com/?p=19095"},{"name":"Ahram Online — Sun alignment at Abu Simbel (2026)","url":"https://english.ahram.org.eg/News/580591.aspx"},{"name":"Original Travel — The Abu Simbel Sun Festival","url":"https://www.originaltravel.co.uk/travel-blog/the-abu-simbel-sun-festival"}],"status":"draft","featured":true,"provenance":"original-ai-assisted","lastReviewed":null,"createdAt":"2026-11-13"}'::jsonb, null, '2026-11-13') on conflict (id) do nothing;
insert into public.media_items (id, title, kind, destinations, status, featured, data, last_reviewed, created_at) values ('nile-three-seasons', 'Three seasons of the Nile', 'original', array['aswan','luxor','cairo']::text[], 'draft', false, '{"id":"nile-three-seasons","title":"Three seasons of the Nile","summary":"Akhet, Peret and Shemu: how one river''s flood shaped farming, taxes and the calendar of ancient Egypt — and why it stopped in the 1960s.","kind":"original","destinations":["aswan","luxor","cairo"],"period":"Ancient Egypt to the 1960s","durationSec":171,"explainerId":"nile-three-seasons","credit":"Discover Egypt (original animation)","license":"© Discover Egypt","chapters":[{"start":0,"title":"A gift of the river"},{"start":14.969,"title":"Black land, red land"},{"start":33.146,"title":"Akhet — inundation"},{"start":55.169,"title":"Peret — emergence"},{"start":68.215,"title":"Shemu — harvest"},{"start":81.262,"title":"Reading the river"},{"start":104.438,"title":"A calendar from the sky"},{"start":129.538,"title":"The flood that stopped"},{"start":154.254,"title":"Where to see it"}],"transcript":[{"start":1.6,"text":"Ancient Egypt lived by one rhythm: the yearly flood of the Nile."},{"start":7.115,"text":"With almost no rain, the river''s rise and fall organised farming, taxes and even the calendar."},{"start":16.569,"text":"Each flood left a layer of fertile black silt across the valley floor."},{"start":22.469,"text":"Egyptians called their country Kemet, the black land."},{"start":26.446,"text":"Beyond it lay Deshret, the red land of the eastern and western deserts."},{"start":34.746,"text":"The year had three seasons of four months each."},{"start":39.108,"text":"Akhet was the season of inundation, when the river spread over the fields."},{"start":45.008,"text":"With the land under water, labour was free for other work, and historians link this season to the great state building projects."},{"start":56.769,"text":"Peret was the season of emergence and growth."},{"start":60.746,"text":"As the water drew back, the soaked black soil appeared and was ploughed and sown."},{"start":69.815,"text":"Shemu was the harvest, when crops ripened and the river ran at its lowest."},{"start":76.1,"text":"Then the flood returned, and the cycle began again."},{"start":82.862,"text":"To forecast the flood, Egyptians measured the river with nilometers marked in cubits."},{"start":88.762,"text":"The nilometer on Elephantine Island at Aswan, near the southern border, was among the first to see the water rise."},{"start":97.354,"text":"Readings passed downstream helped predict the harvest — and the taxes that would follow."},{"start":106.038,"text":"Egyptians noticed that the bright star Sirius, which they called Sopdet, reappeared at dawn before the flood."},{"start":113.477,"text":"Their civil calendar had 365 days: twelve months of thirty days in three seasons, plus five extra days."},{"start":121.3,"text":"With no leap years it slowly drifted, so the season names only sometimes matched the real flood."},{"start":131.138,"text":"In the 1960s, the Aswan High Dam was built to control the river."},{"start":137.038,"text":"Lake Nasser formed behind it, and the yearly flood that had shaped Egypt for thousands of years came to an end."},{"start":146.015,"text":"The rising lake also threatened the temples of Nubia — the story of our Abu Simbel film."},{"start":155.854,"text":"In Aswan, you can still walk down the nilometer on Elephantine Island and see the marks on its walls."},{"start":164.062,"text":"Every claim in this film is listed with its source below the video."}],"sources":[{"name":"Flooding of the Nile — Wikipedia","url":"https://en.wikipedia.org/wiki/Flooding_of_the_Nile"},{"name":"Egyptian calendar — Wikipedia","url":"https://en.wikipedia.org/wiki/Egyptian_calendar"},{"name":"Nile Scribes — The ancient Egyptian calendar","url":"https://nilescribes.org/2017/12/20/the-ancient-egyptian-calendar/"},{"name":"History of Egypt — The flood and the nilometers","url":"https://historyofegypt.net/?p=520"}],"status":"draft","featured":false,"provenance":"original-ai-assisted","lastReviewed":null,"createdAt":"2026-11-13"}'::jsonb, null, '2026-11-13') on conflict (id) do nothing;
insert into public.media_items (id, title, kind, destinations, status, featured, data, last_reviewed, created_at) values ('whe-hatshepsut', 'Hatshepsut: the forgotten woman who was a king of Egypt', 'youtube', array['luxor']::text[], 'draft', false, '{"id":"whe-hatshepsut","title":"Hatshepsut: the forgotten woman who was a king of Egypt","summary":"World History Encyclopedia''s film on Hatshepsut, the female pharaoh whose mortuary temple at Deir el-Bahari is one of the great sights of Luxor''s West Bank.","kind":"youtube","destinations":["luxor"],"period":"New Kingdom, 18th Dynasty","durationSec":null,"youtubeId":"-qw-_IHkKoI","channel":"World History Encyclopedia","credit":"World History Encyclopedia","license":"Standard YouTube licence — embedded from the creator''s channel, not re-uploaded","chapters":[],"transcript":[],"sources":[{"name":"World History Encyclopedia — video listing","url":"https://www.worldhistory.org/video/2767/the-great-pyramid-of-giza-in-egypt/"}],"status":"draft","featured":false,"provenance":"curated-embed","lastReviewed":null,"createdAt":"2026-11-13"}'::jsonb, null, '2026-11-13') on conflict (id) do nothing;
insert into public.media_items (id, title, kind, destinations, status, featured, data, last_reviewed, created_at) values ('whe-ptolemaic-dynasty', 'The Ptolemaic dynasty of ancient Egypt: from Ptolemy I to Cleopatra VII', 'youtube', array['alexandria']::text[], 'draft', false, '{"id":"whe-ptolemaic-dynasty","title":"The Ptolemaic dynasty of ancient Egypt: from Ptolemy I to Cleopatra VII","summary":"World History Encyclopedia''s film on the Greek-speaking dynasty that ruled from Alexandria for three centuries, ending with Cleopatra.","kind":"youtube","destinations":["alexandria"],"period":"Ptolemaic period, 305–30 BCE","durationSec":null,"youtubeId":"0Qi_yw5-qCg","channel":"World History Encyclopedia","credit":"World History Encyclopedia","license":"Standard YouTube licence — embedded from the creator''s channel, not re-uploaded","chapters":[],"transcript":[],"sources":[{"name":"World History Encyclopedia — video listing","url":"https://www.worldhistory.org/video/2767/the-great-pyramid-of-giza-in-egypt/"}],"status":"draft","featured":false,"provenance":"curated-embed","lastReviewed":null,"createdAt":"2026-11-13"}'::jsonb, null, '2026-11-13') on conflict (id) do nothing;
